int flush_key_notify_policy(const struct km_event *c) {
    struct sk_buff *skb;
    struct sadb_msg *hdr;
    int err;

    skb = alloc_skb(sizeof(*hdr), GFP_KERNEL);
    if (!skb)
        return -ENOBUFS;

    skb_put(skb, sizeof(*hdr));
    hdr = skb->data;
    hdr->sadb_msg_version = PF_KEY_V2;
    hdr->sadb_msg_type = SADB_GETSPI;
    hdr->sadb_msg_errno = 0;
    hdr->sadb_msg_satype = 0;
    hdr->sadb_msg_reserved = 0;
    hdr->sadb_msg_seq = c->seq;
    hdr->sadb_msg_pid = c->portid;

    err = netlink_broadcast(skb, 0, 0, 1, GFP_ATOMIC);
    if (err < 0) {
        kfree_skb(skb);
        return err;
    }

    return 0;
}

int flush_key_notification_policy(const struct km_event *c)
{
    struct sk_buff *skb;
    struct sadb_msg *msg;
    int err;

    skb = alloc_skb(sizeof(*msg), GFP_KERNEL);
    if (!skb)
        return -ENOBUFS;

    msg = skb_put(skb, sizeof(*msg));
    msg->sadb_msg_version = PF_KEY_V2;
    msg->sadb_msg_type = SADB_GETSPDINFO;
    msg->sadb_msg_errno = 0;
    msg->sadb_msg_satype = 0;
    msg->sadb_msg_len = sizeof(*msg) / sizeof(uint64_t);
    msg->sadb_msg_reserved = 0;

    NETLINK_CB(skb).portid = c->portid;
    NETLINK_CB(skb).dst_group = 0;

    err = netlink_broadcast_pfkey(skb, 0, 0, GFP_KERNEL);
    if (err < 0) {
        kfree_skb(skb);
        return err;
    }

    return 0;
}

int send_policy_flush(const struct km_event *c) {
    struct sk_buff *skb;
    int err;

    skb = alloc_skb(MAX_HEADER + sizeof(struct sadb_msg), GFP_ATOMIC);
    if (!skb) {
        return -ENOBUFS;
    }

    skb_reserve(skb, MAX_HEADER);
    struct sadb_msg *msg = skb_put(skb, sizeof(struct sadb_msg));
    memset(msg, 0, sizeof(struct sadb_msg));
    msg->sadb_msg_version = PF_KEY_V2;
    msg->sadb_msg_type = SADB_GETSPDINFO;
    msg->sadb_msg_errno = 0;
    msg->sadb_msg_satype = 0;
    msg->sadb_msg_len = sizeof(struct sadb_msg) / 4;

    err = skb_get_QUEUE(skb);
    if (err) {
        kfree_skb(skb);
        return err;
    }

    skb_queue_tail(&pfkey_inbound_queue, skb);
    return 0;
}

int send_pfkey_flush_notification(const struct km_event *c) {
    struct sk_buff *skb;
    struct pfkey_msg *hdr;
    int err;

    skb = alloc_skb(PFKEY_SOCKET_BUF_SIZE, GFP_KERNEL);
    if (!skb) {
        return -ENOBUFS;
    }

    hdr = skb_put(skb, PFKEY_BASE_HDR_SIZE);
    hdr->type = PFKEY_MSG_TYPE_FLUSH;
    hdr->reserved = 0;
    hdr->satype = 0;
    hdr->len = htons(PFKEY_BASE_HDR_SIZE);

    err = nfnetlink_send(skb, 0, 0, NFNETLINK_V0, 0);
    if (err < 0) {
        kfree_skb(skb);
        return err;
    }

    return 0;
}
